{'command': 'python3 -c "
import json

with open('trajectory.json', 'r') as f:
    trajectory = json.loads(json.load(f))
steps = trajectory.get('steps', [])

out_lines = []
for i, step in enumerate(steps):
    source = step.get('source')
    if source == 'user':
        out_lines.append(f'=== STEP {i} - USER ===')
        out_lines.append(step.get('message', ''))
    elif source == 'agent':
        out_lines.append(f'=== STEP {i} - AGENT ===')
        msg = step.get('message', '')
        if msg:
            out_lines.append(f'Message: {msg}')
        tool_calls = step.get('tool_calls', [])
        for tc in tool_calls:
            out_lines.append(f\"Tool: {tc.get('function_name')} | Args: {json.dumps(tc.get('arguments'))}\")

        obs = step.get('observation', {})
        if obs and 'results' in obs:
            for r in obs['results']:
                obs_content = r.get('content', '')
                if len(obs_content) > 500:
                    obs_content = obs_content[:500] + '... [TRUNCATED]'
                out_lines.append(f'Observation: {obs_content}')

with open('parsed_log.txt', 'w') as f:
    f.write('\n'.join(out_lines))
"'}
